//! Photoshop's area-text first-baseline formula.
//!
//! Photoshop places the first baseline of area text at `ratio * point size`
//! below the box top, where `ratio` is the ink `yMax` of `d` over the em square
//! (`Face::ascent_ratio`, which falls back to `b`, `h`, `H` and finally
//! `hhea`). This file replays the two measured tables:
//!
//! * `tests/data/font_ascent.json` - 14 fonts calibrated from Photoshop PDF
//!   exports of area text (generated by `tools/measure_baseline.py`).
//! * the table below - 13 fonts from `out/probe5/font_ratios.json`, measured by
//!   scanning the baseline offset of `<font>` layer pairs at several sizes
//!   (`out/probe5/ratio.pdf`).
//!
//! The tolerance is 0.0012 em: the probes read the baseline through PDF glyph
//! positions, whose 3-decimal coordinates quantise the ratio; the largest
//! observed deviation (Vampire95) is 0.00103.

use std::path::PathBuf;

use photocraft_text::area::{first_baseline, first_baseline_offset, first_baseline_ratio};
use photocraft_text::font::Face;

/// Font files the two measured tables refer to. The names come from the probe
/// artifacts (`out/probe5/font_ratios.json` `file` fields and the Wine font
/// directory), not from a guess: the CC files write the style after a space
/// while their Photoshop family names use a dash, and the older "Italic" style
/// is stored as `... RegularItalic.otf`.
const FONT_FILES: &[(&str, &str)] = &[
    ("NotoSans-Regular", "NotoSans-Regular.ttf"),
    ("NotoSans-Bold", "NotoSans-Bold.ttf"),
    ("NotoSerif-Regular", "NotoSerif-Regular.ttf"),
    ("ArialMT", "arial.ttf"),
    ("CCGrimNGritty-Bold", "CCGrimNGritty Bold.otf"),
    ("CCGrimNGritty-BoldItalic", "CCGrimNGritty BoldItalic.otf"),
    ("CCGrimNGritty-Regular", "CCGrimNGritty Regular.otf"),
    ("CCGrimNGritty-Italic", "CCGrimNGritty RegularItalic.otf"),
    ("CCMeanwhile", "CCMeanwhile.otf"),
    ("CCMeanwhile-Bold", "CCMeanwhile-Bold.otf"),
    ("CCMeanwhile-BoldItalic", "CCMeanwhile-BoldItalic.otf"),
    ("CCMeanwhile-Italic", "CCMeanwhile-Italic.otf"),
    ("CCSpellcaster", "CCSpellcaster.otf"),
    ("CCSpellcaster-Bold", "CCSpellcaster Bold.otf"),
    ("CCSpellcaster-BoldItalic", "CCSpellcaster BoldItalic.otf"),
    ("v_10CentComics", "v_10CentComics_v2.0.ttf"),
    ("v_AgencyFB-Reg", "v_AgencyFB_v1.1.ttf"),
    ("Vampire95", "vampire.ttf"),
    ("v_AlterEgoBB", "v_AlterEgoBB_v1.26.ttf"),
    ("v_CCPrimalScream", "v_CCPrimalScream_v2.01.ttf"),
    ("v_CCPulpFiction-Medium", "v_CCPulpFictionMedium_v1.2.ttf"),
    ("v_CCRumble", "v_CCRumble_v1.0.ttf"),
    ("v_CCMonsterMash", "v_CCMonsterMash_v1.03.ttf"),
    ("v_CCPhasesOnStunMedium", "v_CCPhasesOnStun_v1.11.ttf"),
];

fn resolve_font(family: &str) -> PathBuf {
    let file = FONT_FILES
        .iter()
        .find(|(name, _)| *name == family)
        .unwrap_or_else(|| panic!("no font file recorded for {family}"))
        .1;
    let wine = PathBuf::from(std::env::var("HOME").expect("HOME"))
        .join(".local/share/photocraft/wine/drive_c/windows/Fonts")
        .join(file);
    if wine.exists() {
        return wine;
    }
    // The probes also drew from the font source directory; fall back to it.
    let src = PathBuf::from("/media/H/anime-set/text_detect/fontas").join(file);
    assert!(
        src.exists(),
        "font {family} not found at {wine:?} or {src:?}"
    );
    src
}

fn with_family_face<R>(family: &str, f: impl FnOnce(&Face<'_>) -> R) -> R {
    let path = resolve_font(family);
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("{path:?}: {e}"));
    let face = Face::parse(&bytes).unwrap_or_else(|e| panic!("{path:?}: {e}"));
    f(&face)
}

#[test]
fn first_baseline_ratio_matches_the_calibrated_font_table() {
    let table: std::collections::BTreeMap<String, f32> =
        serde_json::from_str(include_str!("data/font_ascent.json")).expect("font_ascent.json");
    assert_eq!(table.len(), 14, "font_ascent.json changed?");
    for (family, measured) in &table {
        with_family_face(family, |face| {
            let got = face.ascent_ratio();
            assert!(
                (got - measured).abs() <= 0.0012,
                "{family}: ink-d ratio {got:.5} vs Photoshop baseline {measured:.5}"
            );
            // The public helpers are the formula, not a lookup table.
            assert_eq!(first_baseline_ratio(face), got);
            assert_eq!(
                first_baseline(face, 36.0),
                first_baseline_offset(face.ascent_ratio(), 36.0)
            );
            assert!((first_baseline(face, 36.0) - measured * 36.0).abs() <= 0.0012 * 36.0);
        });
    }
}

#[test]
fn first_baseline_ratio_matches_the_probe_font_table() {
    // out/probe5/font_ratios.json, measured through out/probe5/ratio.pdf.
    // `ratio` is Photoshop's area-text baseline offset / size. The font's exact
    // d/upm is the second column (from the same probe, computed by fontTools
    // from the outlines); the formula has to land within 0.0012 of Photoshop.
    const MEASURED: [(&str, f32); 12] = [
        ("NotoSans-Regular", 0.760),
        ("NotoSerif-Regular", 0.760278),
        ("CCGrimNGritty-Regular", 0.781111),
        ("v_10CentComics", 0.800),
        ("v_AgencyFB-Reg", 0.764444),
        ("Vampire95", 0.465),
        ("v_AlterEgoBB", 0.674167),
        ("v_CCPrimalScream", 0.704444),
        ("v_CCPulpFiction-Medium", 0.778889),
        ("v_CCRumble", 0.814167),
        ("v_CCMonsterMash", 0.600278),
        ("v_CCPhasesOnStunMedium", 0.798056),
        // CCSpellcaster is skipped here: the probe's entry (6.2655) is bogus (it
        // divides by a glyph-relative size, not the em), and the regular weight
        // was not calibrated. The calibrated table above covers its Bold and
        // BoldItalic at 0.86.
    ];
    for (family, measured) in MEASURED {
        with_family_face(family, |face| {
            let got = face.ascent_ratio();
            assert!(
                (got - measured).abs() <= 0.0012,
                "{family}: ink-d ratio {got:.5} vs measured baseline ratio {measured:.5}"
            );
        });
    }
}

#[test]
fn first_baseline_scales_linearly_with_size() {
    with_family_face("NotoSans-Regular", |face| {
        let ratio = face.ascent_ratio();
        assert!((ratio - 0.76).abs() < 1e-6);
        for size in [6.0f32, 12.0, 24.0, 72.0, 300.0] {
            assert_eq!(first_baseline(face, size), ratio * size);
        }
        // The measured Photoshop baseline of Noto Sans area text is exactly
        // 0.76 * size for every probed size (out/probe5/ratio.pdf).
        for size in [9.0f32, 18.0, 36.0, 96.0] {
            assert!((first_baseline(face, size) - 0.76 * size).abs() < 1e-4);
        }
    });
}
